import React, { useState } from 'react';
import { Switch, Form, Input, useValidate } from '@cloud-materials/common';
import { IconCheckCircleFill, IconCloseCircleFill } from '@arco-design/iconbox-react-ve-o-design';

export default () => {
  const [value, setValue] = useState('');
  const [isStopAtFirstError, setStopAtFirstError] = useState(false);
  const { valid, errors } = useValidate({
    value,
    rules: [
      {
        message: '长度需要在2-128个字符内',
        minLength: 2,
        maxLength: 128,
      },
      {
        match: /^[\u4e00-\u9fa5a-zA-Z0-9_-]+$/,
        message: '只能包含中文、字母、数字、下划线和中划线',
      },
      {
        match: /^[^0-9-]/,
        message: '不能以数字、中划线开头',
      },
    ],
    stopAtFirstError: isStopAtFirstError,
  });
  return (
    <div style={{ width: 500 }}>
      <Form>
        <Form.Item label="开启 单条校验">
          <Switch checked={isStopAtFirstError} onChange={setStopAtFirstError} />
        </Form.Item>
        <Form.Item label="待验证">
          <Input value={value} onChange={setValue} placeholder="输入数字 1，并切换上方单条验证的开关" />
        </Form.Item>
        <Form.Item label="校验结果">{valid ? <IconCheckCircleFill /> : <IconCloseCircleFill />}</Form.Item>
        <Form.Item label="报错信息">{JSON.stringify(errors.map(error => error.message))}</Form.Item>
        <Form.Item label="错误 key">{JSON.stringify(errors.map(error => error.key))}</Form.Item>
      </Form>
    </div>
  );
};

