import React from 'react';
import { CPopoverVerifyFormItem, Form, Input, Button, Message, Radio } from '@cloud-materials/common';

const rulesUser = [
  {
    message: '必须输入user',
    validator(val: any, cb: any) {
      if (val !== 'user') {
        return cb('必须输入user');
      } else {
        return cb();
      }
    },
    key: 'user',
  },
];

const rulesAdmin = [
  {
    message: '必须输入admin',
    validator(val: any, cb: any) {
      if (val !== 'admin') {
        return cb('必须输入admin');
      } else {
        return cb();
      }
    },
    key: 'admin',
  },
];

export default () => {
  const [form] = Form.useForm();

  return (
    <>
      <Form form={form}>
        <Form.Item label="规则" field="rule" initialValue={'user'}>
          <Radio.Group>
            <Radio value={'user'}>必须输入user</Radio>
            <Radio value={'admin'}>必须输入admin</Radio>
          </Radio.Group>
        </Form.Item>
        <Form.Item shouldUpdate noStyle>
          {values => {
            const rule = values.rule;
            const currentRules = rule === 'user' ? rulesUser : rulesAdmin;
            return (
              <CPopoverVerifyFormItem
                label="账户名称"
                field="account"
                rules={currentRules}
                cPopoverVerifyProps={{ validateOnRulesChange: true }}
              >
                <Input style={{ width: 200 }} />
              </CPopoverVerifyFormItem>
            );
          }}
        </Form.Item>

        <Form.Item wrapperCol={{ offset: 5 }}>
          <Button
            type="primary"
            onClick={async () => {
              try {
                const value = await form.validate();
                console.log(value);
                Message.success('提交表单');
              } catch (_) {
                const error = form.getFields();
                console.log(error);
              }
            }}
          >
            提交
          </Button>
        </Form.Item>
      </Form>
    </>
  );
};

